/// 10^(dB/20) = 2^n * P(f), dB K = n + f; P degree 2 with P(0) = 1, P(1) = 2 exactly:
/// continuous at every 6.02 dB and exactly 1 at 0 dB. Gain must stay a normal float.
template<typename T>
inline auto db_to_gain_2(T db) -> T
{
    const auto t = db * T(0.1660964047443681);
    const auto r = std::floor(t);
    const auto f = t - r;
    auto p = T(0.33976602913477555);
    p = p * f + T(0.6602339708652245);
    p = p * f + T(1.0);
    return pow2i<T>(static_cast<ieee_int<T>>(r)) * p;
}

